scwin.onpageunload = function() {};
scwin.trigger1_onclick = function(e) {
    var options = {
        type: "1",
        fileName: "excel.xlsx"
    };
    gridView1.advancedExcelDownload(options);
};
scwin.trigger2_onclick = function(e) {
    var options = {
        type: "1",
        startRowIndex: "0",
        headerExist: "1"
    };
    gridView1.advancedExcelUpload(options);
};
scwin.gridView1_onafteredit = function(row, col, value) {
    var sum = dataList2.getColSum("col4");
    console.log("sum: ", sum);
    //gridView1.setHeaderValue("column3", sum, true);
};
scwin.tooltipFormatter = function(rowIndex, colIndex, label, isOverflow) {
    //console.log(" rowIndex, colIndex, label, isOverflow: ", rowIndex, colIndex, label, isOverflow);
    if (label.length > 300 && isOverflow == true) {
        console.log("tooltip overFlow!!");
        return label.substring(0, 300) + " ...";
    }
    return label;
};
scwin.gridView1_onviewchange = function(info) {
    console.log("onviewchange: ", info);
};
scwin.simulateWrapper = function(target, type, options) {
    WebSquare.wUnit.getJq(target).simulate(type, options);
}
scwin.setVal2 = function() {
    scwin.simulateWrapper('#G_gridView1__col1', 'key-combo', {
        combo: 'ENTER'
    });
}
scwin.setVal1 = function() {
    scwin.simulateWrapper('#G_gridView1__col1', 'key-sequence', {
        sequence: 'ccc'
    });
}
scwin.Dbclick = function(id) {
    var el = WebSquare.wUnit.getDomById(id);
    scwin.fireDbClick(el);
}
scwin.fireDbClick = function(node) {
    if (document.createEventObject) {
        node.fireEvent('ondblclick');
    } else if (document.createEvent) {
        var evt = document.createEvent('MouseEvents');
        evt.initEvent('dblclick', true, false);
        node.dispatchEvent(evt);
    } else if (typeof node.ondblclick == 'function') {
        node.ondblclick();
    }
}
scwin.unitTest = function() {
    //Unit
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "scwin.Dbclick('gridView1_cell_0_0')");
    WebSquare.wUnit.addCommand('pause', '500');
    WebSquare.wUnit.addCommand("set", "scwin.setVal1()");
    WebSquare.wUnit.addCommand('pause', '500');
    WebSquare.wUnit.addCommand("set", "scwin.setVal2()");
    WebSquare.wUnit.addCommand('pause', '500');
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getDomById('gridView1_column3').innerText == '1,000,000'", "true");
    WebSquare.wUnit.addCommand('pause', '500');
    //Run test and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.unitTest();
